from html import escape
from pathlib import Path
def generate(session, events, result, out):
    rows=''.join(f"<tr><td>{e['ts_ms']}</td><td>{escape(e['channel'])}</td><td>{escape(e['event_type'])}</td><td>{'demo' if e.get('demo') else 'observed'}</td></tr>" for e in events)
    flags=''.join(f"<li><b>{escape(f['rule_id'])}</b>: {escape(f['explanation'])}</li>" for f in result['flags']) or '<li>No flags</li>'
    html=f"""<!doctype html><html><head><meta charset="utf-8"><title>ProctorStream report {escape(session['id'])}</title><style>body{{font:16px system-ui;max-width:1000px;margin:40px auto;color:#172033}}table{{width:100%;border-collapse:collapse}}td,th{{padding:8px;border-bottom:1px solid #ddd;text-align:left}}.risk{{font-size:2em;font-weight:700}}</style></head><body><h1>ProctorStream session report</h1><p><b>Session:</b> {escape(session['id'])} &nbsp; <b>Candidate:</b> {escape(session['candidate_id'])}</p><div class="risk">Risk: {escape(result['risk_level'])}</div><p>Recommendation: {escape(result['recommendation'])}</p><p><b>Available channels:</b> {escape(', '.join(result['available_channels']) or 'none')}<br><b>Missing channels:</b> {escape(', '.join(result['missing_channels']) or 'none')}</p><h2>Flags</h2><ul>{flags}</ul><h2>Timeline</h2><table><tr><th>Time (ms)</th><th>Channel</th><th>Event</th><th>Source</th></tr>{rows}</table><hr><p><b>Disclaimer:</b> Automated flags are triage signals and require human review. Demo events are synthetic and are not evidence of model accuracy.</p></body></html>"""
    Path(out).write_text(html); return out
